int get_dest_keyring(struct key **_dest_keyring) {
    struct key *dest_keyring = NULL;
    int ret = 0;

    if (!_dest_keyring)
        return -EINVAL;

    /* Use a provided keyring if available */
    if (*_dest_keyring) {
        dest_keyring = *(_dest_keyring);
    } else {
        /* Default to the user's session keyring if not provided */
        dest_keyring = current->thread_keyring;
        if (!dest_keyring) {
            dest_keyring = request_key(NULL, NULL, NULL, 0);
            if (IS_ERR(dest_keyring))
                return PTR_ERR(dest_keyring);
        }

        /* Ensure the process has write access to the keyring */
        ret = key_permission(current_cred(), dest_keyring, KEY_NEED_WRITE);
        if (ret < 0) {
            key_put(dest_keyring);
            return ret;
        }
    }

    *_dest_keyring = dest_keyring;
    return 0;
}

int get_dest_keyring(struct key **_dest_keyring) {
    struct key *keyring = *_dest_keyring;

    if (keyring == NULL) {
        keyring = current_user()->user_keyring;
        if (keyring == NULL) {
            return -ENOENT;
        }
    }

    if (key_task_perm(keyring, current_cred(), KEY_SEARCH)) {
        return -EACCES;
    }

    *_dest_keyring = keyring;
    return 0;
}

#include <linux/key.h>
#include <linux/errno.h>

int get_dest_keyring(struct key **_dest_keyring) {
    struct key *dest_keyring = NULL;
    struct key *default_keyring = NULL;
    int ret = 0;

    if (_dest_keyring && *_dest_keyring) {
        dest_keyring = *_dest_keyring;
        ret = key_permission(dest_keyring, KEY_POS_WRITE);
        if (ret)
            return ret;
    } else {
        key_ref_t key_ref;
        key_ref = key_lookup(KEY_SPEC_USER_KEYRING, 0, 0);
        if (IS_ERR(key_ref))
            return PTR_ERR(key_ref);

        default_keyring = key_ref_to_ptr(key_ref);
        ret = key_permission(default_keyring, KEY_POS_WRITE);
        if (ret) {
            key_put(default_keyring);
            return ret;
        }

        dest_keyring = default_keyring;
    }

    *_dest_keyring = dest_keyring;
    return 0;
}
